BAD = [(2, 2, 2), (2, 4, 1), (1, 2, 1), (0, 0, 1)]

def score(b):
    g = b.grid
    h0, h1 = b.heights[0], b.heights[1]
    if h0 + h1 > 4:
        return 0
    s = sum(g[r][c] == v for r, c, v in SIG) - sum(g[r][c] == v for r, c, v in BAD)
